import{_ as i,o as a,c as s,aj as o}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"NgModule.id Set to module.id anti-pattern","description":"","frontmatter":{},"headers":[],"relativePath":"en/errors/NG6100.md","filePath":"en/errors/NG6100.md"}'),t={name:"en/errors/NG6100.md"};function d(n,e,r,l,c,p){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="ngmodule-id-set-to-module-id-anti-pattern" tabindex="-1">NgModule.id Set to module.id anti-pattern <a class="header-anchor" href="#ngmodule-id-set-to-module-id-anti-pattern" aria-label="Permalink to &quot;NgModule.id Set to module.id anti-pattern&quot;">​</a></h1><p>Using <code>module.id</code> as an NgModule <code>id</code> is a common anti-pattern and is likely not serving a useful purpose in your code.</p><p>NgModules can be declared with an <code>id</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">NgModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my_module&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MyModule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span></code></pre></div><p>Declaring an <code>id</code> makes the NgModule available for lookup via the <code>getNgModuleById()</code> operation. This functionality is rarely used, mainly in very specific bundling scenarios when lazily loading NgModules without obtaining direct references to them. In most Angular code, ES dynamic <code>import()</code> (<code>import(&#39;./path/to/module&#39;)</code>) should be used instead, as this provides a direct reference to the NgModule being loaded without the need for a global registration side effect.</p><p>If you are not using <code>getNgModuleById</code>, you do not need to provide <code>id</code>s for your NgModules. Providing one has a significant drawback: it makes the NgModule non-tree-shakable, which can have an impact on your bundle size.</p><p>In particular, the pattern of specifying <code>id: module.id</code> results from a misunderstanding of <code>@NgModule.id</code>. In earlier versions of Angular, it was sometimes necessary to include the property <code>moduleId: module.id</code> in <code>@Component</code> metadata.</p><h2 id="debugging-the-error" tabindex="-1">Debugging the error <a class="header-anchor" href="#debugging-the-error" aria-label="Permalink to &quot;Debugging the error&quot;">​</a></h2><p>You can remove the <code>id: module.id</code> declaration from your NgModules. The compiler ignores this declaration and issues this warning instead.</p>`,9)]))}const g=i(t,[["render",d]]);export{u as __pageData,g as default};
